parameters.jsCode:
// === Zentrale Konfiguration – hier pflegen ===

// Zeitraum "Bestellungen des letzten Monats":
// 'rollierend' = heute vor einem Monat bis jetzt (Zeitpunkt des manuellen Starts)
// 'vormonat'   = 1. bis letzter Tag des Vormonats (deutsche Zeit)
const ZEITRAUM = 'rollierend';

const heute = DateTime.now().setZone('Europe/Berlin');
let von = heute.minus({ months: 1 });
let bis = null;
if (ZEITRAUM === 'vormonat') {
  von = heute.startOf('month').minus({ months: 1 });
  bis = heute.startOf('month').minus({ seconds: 1 });
}

const CONFIG = {
  shop: 'vdzvc0-nd',
  apiVersion: '2024-10',

  zeitraum: ZEITRAUM,
  // Wird bei jedem Lauf neu berechnet, daher kein fixes Datum im Code.
  createdAtMin: von.toUTC().toISO(),
  // null = "bis jetzt"
  createdAtMax: bis ? bis.toUTC().toISO() : null,

  // Bestellliste per GraphQL. 100 pro Seite = ca. 700 angefragte Punkte,
  // Shopify erlaubt hoechstens 1.000 pro Query.
  seitenGroesse: 100,
  // Notbremse gegen einen kaputten Cursor. Greift sie, meldet der Report UNVOLLSTAENDIG.
  maxSeiten: 100,
  // So oft darf Shopify eine Seite drosseln (THROTTLED), bevor der Lauf abbricht.
  maxDrosselungen: 20,

  // Offene Bestellungen, deren erste Zahlungsaufforderung so viele Tage alt ist,
  // werden im Report markiert (kein Filter).
  alterTage: 14,

  // Timeline-Eintraege, die als Zahlungsaufforderung zaehlen (Regex, Gross-/
  // Kleinschreibung egal). Nach dem ersten Lauf mit dem DIAGNOSE-Item aus
  // 'Report erstellen' abgleichen und bei Bedarf ergaenzen.
  aufforderungMuster: 'zahlungsaufforderung|zahlungsanforderung|zahlung angefordert|'
    + 'zahlungserinnerung|zahlungslink|rechnung|payment request|payment reminder|'
    + 'payment link|invoice|bestellung bearbeitet|bestellbearbeitung|order edited',
  // ... und muessen ein Mailversand sein: action 'mail_sent' oder dieser Text.
  gesendetMuster: 'gesendet|versendet|verschickt|\\bsent\\b',

  // Einzelne Bestellungen ausschliessen (orderId als Zahl)
  ausnahmen: []
};

const staticData = $getWorkflowStaticData('global');
staticData.kandidaten = [];
staticData.ergebnisse = {};
staticData.unlesbar = [];
staticData.teilbezahltSonstige = [];
staticData.abgebrochen = false;
staticData.diagnose = { erkannt: {}, nichtErkannt: {} };
staticData.stats = {
  seiten: 0, geprueft: 0, bearbeitet: 0, storniert: 0, ausnahmen: 0, gedrosselt: 0,
  statusVerteilung: {}
};

return [{ json: { config: CONFIG } }];

const config = $('Config').first().json.config;
// Erste Runde kommt aus 'Config' (kein Cursor), danach aus 'Weitere Seite?'.
const cursor = $input.first().json.cursor || null;

// Voller Zeitstempel statt nur Datum, damit das Fenster exakt dem Config-Zeitraum entspricht.
let filter = `created_at:>='${config.createdAtMin}'`;
if (config.createdAtMax) {
  filter += ` AND created_at:<='${config.createdAtMax}'`;
}

// edited + Original- und aktuelle Summe erkennen einen Mehrbetrag aus einer
// Bearbeitung auch dann noch, wenn er schon bezahlt ist (Saldo 0).
const query = `query($cursor: String, $filter: String) {
  orders(first: ${config.seitenGroesse}, after: $cursor, query: $filter, sortKey: CREATED_AT) {
    edges {
      node {
        id
        name
        createdAt
        cancelledAt
        edited
        displayFinancialStatus
        originalTotalPriceSet { presentmentMoney { amount currencyCode } }
        totalPriceSet         { presentmentMoney { amount currencyCode } }
        totalOutstandingSet   { presentmentMoney { amount currencyCode } }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}`;

return [{
  json: {
    cursor,
    filter,
    gqlBody: JSON.stringify({ query, variables: { cursor, filter } })
  }
}];

const resp = $input.first().json;
const config = $('Config').first().json.config;
const staticData = $getWorkflowStaticData('global');
const stats = staticData.stats;

// Shopify rechnet mit einem Punkte-Bucket, der je nach Plan unterschiedlich schnell
// nachlaeuft. Gewartet wird, bis wieder genug Punkte fuer die naechste Seite da sind.
const kosten = resp?.extensions?.cost;
const warteSek = (benoetigt) => {
  const t = kosten?.throttleStatus;
  if (!t || !(t.restoreRate > 0)) return 1;
  return Math.max(1, Math.ceil((benoetigt - t.currentlyAvailable) / t.restoreRate));
};

const errors = Array.isArray(resp?.errors) ? resp.errors : [];

// THROTTLED kommt mit HTTP 200: dieselbe Seite nach der Pause noch einmal holen.
if (errors.some(e => e?.extensions?.code === 'THROTTLED')) {
  stats.gedrosselt++;
  if (stats.gedrosselt > config.maxDrosselungen) {
    throw new Error(`Shopify drosselt dauerhaft (${stats.gedrosselt}x THROTTLED) – Lauf abgebrochen.`);
  }
  return [{
    json: {
      cursor: $('Query bauen (Liste)').first().json.cursor,
      hasNext: true,
      gedrosselt: true,
      wartenSek: warteSek(kosten?.requestedQueryCost || 1000)
    }
  }];
}

// Andere GraphQL-Fehler kommen ebenfalls mit HTTP 200. Hart abbrechen:
// mit einer halben Bestellliste waeren alle Zahlen im Report falsch.
if (errors.length) {
  throw new Error('GraphQL-Fehler: ' + JSON.stringify(errors).slice(0, 1000));
}
const conn = resp?.data?.orders;
if (!conn) {
  throw new Error('Keine Orders-Antwort: ' + JSON.stringify(resp).slice(0, 500));
}

stats.seiten++;

// Betraege kommen als String. null/'' waeren bei Number() eine 0 -> vorher abfangen.
const geld = (set) => {
  const roh = set?.presentmentMoney?.amount;
  return (roh === null || roh === undefined || roh === '') ? NaN : Number(roh);
};
const cent = (v) => Math.round(v * 100);

const knoten = (conn.edges || []).map(e => e.node);

for (const o of knoten) {
  stats.geprueft++;
  const status = o.displayFinancialStatus || 'UNBEKANNT';
  stats.statusVerteilung[status] = (stats.statusVerteilung[status] || 0) + 1;
  if (o.edited) stats.bearbeitet++;

  const orderId = Number(String(o.id).split('/').pop());
  if (Array.isArray(config.ausnahmen) && config.ausnahmen.includes(orderId)) {
    stats.ausnahmen++;
    continue;
  }

  const original = geld(o.originalTotalPriceSet);
  const aktuell = geld(o.totalPriceSet);
  const offen = geld(o.totalOutstandingSet);
  const currency = o.totalPriceSet?.presentmentMoney?.currencyCode
    || o.originalTotalPriceSet?.presentmentMoney?.currencyCode;
  const adminUrl = `https://admin.shopify.com/store/${config.shop}/orders/${orderId}`;

  if (o.edited && ![original, aktuell, offen].every(Number.isFinite)) {
    staticData.unlesbar.push({
      orderId, orderName: o.name, createdAt: o.createdAt, adminUrl,
      grund: 'Beträge unlesbar: ' + JSON.stringify({
        original: o.originalTotalPriceSet, aktuell: o.totalPriceSet, offen: o.totalOutstandingSet
      })
    });
    continue;
  }

  // Mehrbetrag aus einer Bearbeitung: Summe heute hoeher als bei Bestellung.
  // Bewusst nicht ueber den Saldo: bereits ausgeglichene Bestellungen stehen auf 0.
  const mehrCent = o.edited ? cent(aktuell) - cent(original) : 0;

  if (mehrCent > 0) {
    if (o.cancelledAt) {
      stats.storniert++;
      continue;
    }
    staticData.kandidaten.push({
      orderId,
      orderName: o.name,
      createdAt: o.createdAt,
      financialStatus: status,
      currency,
      originalBetrag: original.toFixed(2),
      aktuellerBetrag: aktuell.toFixed(2),
      mehrbetrag: (mehrCent / 100).toFixed(2),
      offenerBetrag: offen.toFixed(2)
    });
    continue;
  }

  // Kontrollliste: jedes 'Partially paid' soll im Report stehen, auch wenn es
  // nicht aus einer Bearbeitung mit Mehrbetrag kommt.
  if (status === 'PARTIALLY_PAID' && !o.cancelledAt) {
    staticData.teilbezahltSonstige.push({
      orderId,
      orderName: o.name,
      createdAt: o.createdAt,
      financialStatus: status,
      currency,
      offenerBetrag: Number.isFinite(offen) ? offen.toFixed(2) : null,
      bearbeitet: !!o.edited,
      mehrbetrag: o.edited ? (mehrCent / 100).toFixed(2) : null,
      adminUrl
    });
  }
}

const serverHatMehr = !!conn.pageInfo?.hasNextPage;
const limitErreicht = stats.seiten >= config.maxSeiten;
if (serverHatMehr && limitErreicht) staticData.abgebrochen = true;

return [{
  json: {
    cursor: conn.pageInfo?.endCursor || null,
    hasNext: serverHatMehr && !limitErreicht,
    wartenSek: warteSek(kosten?.requestedQueryCost || 0),
    seite: stats.seiten,
    seiteBestellungen: knoten.length,
    bestellungenGeprueft: stats.geprueft,
    kandidatenGesamt: staticData.kandidaten.length
  }
}];

const config = $('Config').first().json.config;
const kandidaten = $getWorkflowStaticData('global').kandidaten || [];

// Ein Item pro Bestellung mit offenem Betrag. Daran haengt die Timeline-Pruefung.
return kandidaten.map(k => ({
  json: {
    ...k,
    orderGid: `gid://shopify/Order/${k.orderId}`,
    adminUrl: `https://admin.shopify.com/store/${config.shop}/orders/${k.orderId}`
  }
}));

// Input dieses Nodes ist 'Token holen 2' (OAuth-Antwort), nicht die Bestellung.
// Die Bestelldaten deshalb direkt aus dem Loop holen.
const item = $('Loop Over Items').first().json;

// Betraege frisch: zwischen Scan und Pruefung kann bezahlt worden sein.
// agreements liefert den Zeitpunkt der Bearbeitung (reason ORDER_EDIT),
// events die Timeline mit allen versendeten Mails.
const body = {
  query: `query($id: ID!) {
    order(id: $id) {
      id
      name
      cancelledAt
      displayFinancialStatus
      email
      paymentGatewayNames
      billingAddress  { name countryCodeV2 }
      shippingAddress { name countryCodeV2 }
      originalTotalPriceSet { presentmentMoney { amount currencyCode } }
      totalPriceSet         { presentmentMoney { amount currencyCode } }
      totalOutstandingSet   { presentmentMoney { amount currencyCode } }
      agreements(first: 50) {
        pageInfo { hasNextPage }
        edges { node { happenedAt reason } }
      }
      events(first: 100) {
        pageInfo { hasNextPage }
        edges {
          node {
            id
            createdAt
            message
            ... on BasicEvent { action }
          }
        }
      }
    }
  }`,
  variables: { id: item.orderGid }
};

return [{
  json: {
    ...item,
    accessToken: $('Token holen 2').first().json.access_token,
    gqlBody: JSON.stringify(body)
  }
}];

const resp = $input.first().json;
const src = $('Loop Over Items').first().json;
const config = $('Config').first().json.config;
const staticData = $getWorkflowStaticData('global');

// message ist ein FormattedString (HTML mit Links) -> reiner Text
const alsText = (html) => String(html ?? '')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim();

// Fuer die Diagnose: Mailadressen und Zahlen raus, damit gleiche Texte zusammenfallen
const vorlage = (ev) => (ev.action || '-') + ' | ' + ev.text
  .replace(/\S+@\S+/g, '<mail>')
  .replace(/\d[\d.,]*/g, '#')
  .slice(0, 160);

const zaehlen = (map, key) => { map[key] = (map[key] || 0) + 1; };

// Betraege kommen als String. null/'' waeren bei Number() eine 0 -> vorher abfangen.
const geld = (set) => {
  const roh = set?.presentmentMoney?.amount;
  return (roh === null || roh === undefined || roh === '') ? NaN : Number(roh);
};
const cent = (v) => Math.round(v * 100);

// Shopify-Bucket: vor dem naechsten Kandidaten warten, bis die Punkte wieder reichen.
const kosten = resp?.extensions?.cost;
const t = kosten?.throttleStatus;
const wartenSek = (t && t.restoreRate > 0)
  ? Math.max(1, Math.ceil((2 * (kosten.requestedQueryCost || 200) - t.currentlyAvailable) / t.restoreRate))
  : 1;

const ergebnis = {
  ...src,
  accessToken: undefined,
  gqlBody: undefined,
  status: null,
  grund: null,
  kunde: '',
  email: '',
  land: null,
  zahlart: '',
  bearbeitetAm: null,
  aufforderungErhalten: false,
  ersteAufforderung: null,
  letzteAufforderung: null,
  anzahlAufforderungen: 0,
  tageSeitAufforderung: null,
  aufforderungAbAlterTage: false,
  erkanntUeber: null
};
const hinweise = [];

// GraphQL-Fehler kommen mit HTTP 200, ein HTTP-Fehler landet dank onError als error-Objekt hier.
const order = resp?.data?.order;
const gqlErrors = (resp?.errors || []).map(e => e.message);

if (!order) {
  ergebnis.status = 'FEHLER';
  hinweise.push(gqlErrors.join('; ')
    || resp?.error?.message
    || ('Keine Order-Daten: ' + JSON.stringify(resp).slice(0, 300)));
} else {
  const adresse = order.billingAddress || order.shippingAddress || {};
  ergebnis.kunde = adresse.name || '';
  ergebnis.email = order.email || '';
  ergebnis.land = adresse.countryCodeV2 || null;
  ergebnis.zahlart = (order.paymentGatewayNames || []).join(', ');
  ergebnis.financialStatus = order.displayFinancialStatus || src.financialStatus;

  const original = geld(order.originalTotalPriceSet);
  const aktuell = geld(order.totalPriceSet);
  const offen = geld(order.totalOutstandingSet);

  if (![original, aktuell, offen].every(Number.isFinite)) {
    ergebnis.status = 'FEHLER';
    hinweise.push('Beträge unlesbar');
  } else {
    const mehrCent = cent(aktuell) - cent(original);
    ergebnis.originalBetrag = original.toFixed(2);
    ergebnis.aktuellerBetrag = aktuell.toFixed(2);
    ergebnis.mehrbetrag = (mehrCent / 100).toFixed(2);
    ergebnis.offenerBetrag = offen.toFixed(2);
    ergebnis.currency = order.totalPriceSet?.presentmentMoney?.currencyCode || src.currency;

    // Erst ab der ersten Bearbeitung gibt es einen Mehrbetrag, den man anfordern kann.
    // Mails davor (z. B. Rechnung zur Bestellung) zaehlen deshalb nicht.
    const edits = (order.agreements?.edges || [])
      .map(e => e.node)
      .filter(a => a?.reason === 'ORDER_EDIT' && a.happenedAt)
      .sort((a, b) => new Date(a.happenedAt) - new Date(b.happenedAt));
    const bearbeitetAm = edits[0]?.happenedAt || null;
    ergebnis.bearbeitetAm = bearbeitetAm;
    if (!bearbeitetAm) hinweise.push('Kein ORDER_EDIT-Agreement gefunden – alle Mails der Timeline geprüft');
    if (order.agreements?.pageInfo?.hasNextPage) hinweise.push('Mehr als 50 Agreements – nur die ersten 50 geprüft');

    // 1 Minute Toleranz: die Mail kann minimal vor dem Agreement gestempelt sein.
    const abMs = bearbeitetAm ? new Date(bearbeitetAm).getTime() - 60000 : -Infinity;

    const muster = new RegExp(config.aufforderungMuster, 'i');
    const gesendet = new RegExp(config.gesendetMuster, 'i');

    const events = (order.events?.edges || [])
      .map(e => ({ ...e.node, text: alsText(e.node?.message) }));
    const istMail = (ev) => ev.action === 'mail_sent' || gesendet.test(ev.text);
    const mailsNachBearbeitung = events
      .filter(ev => istMail(ev) && new Date(ev.createdAt).getTime() >= abMs);
    const treffer = mailsNachBearbeitung
      .filter(ev => muster.test(ev.text))
      .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));

    if (order.events?.pageInfo?.hasNextPage) {
      hinweise.push('Timeline hat mehr als 100 Einträge – nur die ersten 100 geprüft');
    }

    if (treffer.length) {
      // Alter ab der ERSTEN Aufforderung: so lange wartet der Shop schon auf das Geld,
      // auch wenn zwischendurch erinnert wurde.
      const erste = treffer[0];
      const letzte = treffer[treffer.length - 1];
      const tage = Math.floor((Date.now() - new Date(erste.createdAt).getTime()) / 86400000);

      ergebnis.aufforderungErhalten = true;
      ergebnis.ersteAufforderung = erste.createdAt;
      ergebnis.letzteAufforderung = letzte.createdAt;
      ergebnis.anzahlAufforderungen = treffer.length;
      ergebnis.tageSeitAufforderung = tage;
      ergebnis.aufforderungAbAlterTage = tage >= config.alterTage;
      ergebnis.erkanntUeber = erste.text.slice(0, 120);
      for (const ev of treffer) zaehlen(staticData.diagnose.erkannt, vorlage(ev));
    } else {
      for (const ev of mailsNachBearbeitung) zaehlen(staticData.diagnose.nichtErkannt, vorlage(ev));
    }

    if (order.cancelledAt) {
      ergebnis.status = 'STORNIERT';
    } else if (mehrCent <= 0) {
      // Zwischen Scan und Pruefung korrigiert
      ergebnis.status = 'KEIN_MEHRBETRAG';
    } else if (cent(offen) > 0) {
      ergebnis.status = 'OFFEN';
      if (cent(offen) > mehrCent) {
        hinweise.push('Offen mehr als der Mehrbetrag – ursprüngliche Zahlung evtl. noch nicht erfasst');
      }
    } else {
      ergebnis.status = 'AUSGEGLICHEN';
    }
  }
}

ergebnis.grund = hinweise.join('; ') || null;
staticData.ergebnisse[src.orderId] = ergebnis;

// Bewusst kein throw: eine fehlerhafte Bestellung soll den Loop nicht stoppen.
return [{ json: { ...ergebnis, wartenSek } }];

const config = $('Config').first().json.config;
const staticData = $getWorkflowStaticData('global');
const kandidaten = staticData.kandidaten || [];
const ergebnisse = staticData.ergebnisse || {};
const stats = staticData.stats || {};
const diagnose = staticData.diagnose || { erkannt: {}, nichtErkannt: {} };

const zeilen = kandidaten.map(k => ergebnisse[k.orderId]
  || { ...k, status: 'NICHT_VERARBEITET', grund: 'Kein Ergebnis – Loop abgebrochen?' });

const nach = (...s) => zeilen.filter(z => s.includes(z.status));
const mitAuff = (liste) => liste.filter(z => z.aufforderungErhalten);
const ohneAuff = (liste) => liste.filter(z => !z.aufforderungErhalten);

// Summe je Waehrung, damit EUR und CHF nicht vermischt werden
const summe = (liste, feld) => {
  const s = {};
  for (const z of liste) s[z.currency || '?'] = (s[z.currency || '?'] || 0) + Number(z[feld] || 0);
  return Object.fromEntries(Object.entries(s).map(([c, v]) => [c, v.toFixed(2)]));
};

// Offen: erst mit Aufforderung (aelteste Aufforderung zuerst), dann ohne (aelteste Bestellung zuerst)
const offen = nach('OFFEN').sort((a, b) =>
  (Number(b.aufforderungErhalten) - Number(a.aufforderungErhalten))
  || ((b.tageSeitAufforderung ?? -1) - (a.tageSeitAufforderung ?? -1))
  || (new Date(a.createdAt) - new Date(b.createdAt)));
const ausgeglichen = nach('AUSGEGLICHEN')
  .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));
const betroffen = [...offen, ...ausgeglichen];

const teilbezahltSonstige = [...(staticData.teilbezahltSonstige || [])]
  .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));

const fehler = [
  ...nach('FEHLER', 'NICHT_VERARBEITET'),
  ...(staticData.unlesbar || []).map(u => ({ ...u, status: 'UNLESBAR' }))
];

const zusammenfassung = {
  zeile: 'ZUSAMMENFASSUNG',
  lauf: new Date().toISOString(),
  zeitraum: config.zeitraum,
  zeitraumVon: config.createdAtMin,
  zeitraumBis: config.createdAtMax || 'jetzt',
  alterTage: config.alterTage,

  paginationVollstaendig: !staticData.abgebrochen,
  seitenGeholt: stats.seiten,
  gedrosselt: stats.gedrosselt,
  bestellungenGeprueft: stats.geprueft,
  bestellungenBearbeitet: stats.bearbeitet,

  // Die drei Fragen: wie viele betroffen, wie viele aufgefordert, wie viele ausgeglichen
  betroffen: betroffen.length,
  summeMehrbetrag: summe(betroffen, 'mehrbetrag'),
  zahlungsaufforderungErhalten: mitAuff(betroffen).length,
  ohneZahlungsaufforderung: ohneAuff(betroffen).length,

  ausgeglichen: ausgeglichen.length,
  ausgeglichenMitAufforderung: mitAuff(ausgeglichen).length,
  ausgeglichenOhneAufforderung: ohneAuff(ausgeglichen).length,
  summeAusgeglichen: summe(ausgeglichen, 'mehrbetrag'),

  offen: offen.length,
  offenMitAufforderung: mitAuff(offen).length,
  offenOhneAufforderung: ohneAuff(offen).length,
  offenAufforderungAbAlterTage: offen.filter(z => z.aufforderungAbAlterTage).length,
  summeOffen: summe(offen, 'offenerBetrag'),

  // Gegenprobe zum Admin-Filter "Partially paid" im selben Zeitraum
  partiallyPaidGesamt: betroffen.filter(z => z.financialStatus === 'PARTIALLY_PAID').length
    + teilbezahltSonstige.length,
  partiallyPaidOhneMehrbetrag: teilbezahltSonstige.length,

  storniert: (stats.storniert || 0) + nach('STORNIERT').length,
  inzwischenKorrigiert: nach('KEIN_MEHRBETRAG').length,
  ausnahmen: stats.ausnahmen,
  fehler: fehler.length,

  statusVerteilung: stats.statusVerteilung || {}
};

// Nur fuer die Kontrolle in n8n, geht nicht in die Mail: welche Mail-Texte nach der
// Bearbeitung als Zahlungsaufforderung erkannt wurden und welche nicht.
const sortiert = (map) => Object.entries(map)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 50)
  .map(([text, anzahl]) => ({ anzahl, text }));

const diagnoseZeile = {
  zeile: 'DIAGNOSE',
  hinweis: 'Mail-Events der Timeline nach der ersten Bearbeitung, Format "action | Text" '
    + '(Mailadressen/Zahlen maskiert). Steht unter nichtErkannt eine Zahlungsaufforderung, '
    + 'Config.aufforderungMuster ergänzen.',
  erkannt: sortiert(diagnose.erkannt),
  nichtErkannt: sortiert(diagnose.nichtErkannt)
};

return [
  { json: zusammenfassung },
  ...offen.map(z => ({ json: { zeile: 'OFFEN', ...z } })),
  ...ausgeglichen.map(z => ({ json: { zeile: 'AUSGEGLICHEN', ...z } })),
  ...teilbezahltSonstige.map(z => ({ json: { zeile: 'TEILBEZAHLT_SONSTIGE', ...z } })),
  ...fehler.map(z => ({ json: { zeile: 'FEHLER', ...z } })),
  { json: diagnoseZeile }
];

// Fasst alle Report-Zeilen zu EINER Mail zusammen.
// Ohne diesen Node wuerde 'Send email' pro Report-Zeile eine Mail schicken.

const items = $input.all().map(i => i.json);
const zus = items.find(i => i.zeile === 'ZUSAMMENFASSUNG') || {};
const offen = items.filter(i => i.zeile === 'OFFEN');
const ausgeglichen = items.filter(i => i.zeile === 'AUSGEGLICHEN');
const sonstige = items.filter(i => i.zeile === 'TEILBEZAHLT_SONSTIGE');
const fehler = items.filter(i => i.zeile === 'FEHLER');

// Listen begrenzen, damit die Mail lesbar bleibt
const MAX_AUSGEGLICHEN = 200;
const MAX_KONTROLLE = 100;

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const datum = (iso) => {
  if (!iso) return '';
  const d = new Date(iso);
  return isNaN(d) ? String(iso) : d.toLocaleDateString('de-DE', {
    timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit', year: 'numeric'
  });
};

const betrag = (v, cur) => Number(v || 0).toLocaleString('de-DE', {
  minimumFractionDigits: 2, maximumFractionDigits: 2
}) + ' ' + (cur || '');

const summenText = (obj) => Object.entries(obj || {})
  .map(([cur, v]) => betrag(v, cur)).join(' + ') || betrag(0, 'EUR');

// Wie die Badges im Shopify-Admin
const STATUS = {
  PARTIALLY_PAID: 'Partially paid', PENDING: 'Payment pending', AUTHORIZED: 'Authorized',
  PAID: 'Paid', PARTIALLY_REFUNDED: 'Partially refunded', REFUNDED: 'Refunded',
  VOIDED: 'Voided', EXPIRED: 'Expired'
};
const statusText = (s) => STATUS[s] || s || '';

const th = 'style="text-align:left;padding:6px 10px;border-bottom:2px solid #ddd;font-size:13px"';
const thR = 'style="text-align:right;padding:6px 10px;border-bottom:2px solid #ddd;font-size:13px"';
const td = 'style="padding:6px 10px;border-bottom:1px solid #eee;font-size:13px;vertical-align:top"';
const tdE = 'style="padding:6px 10px 6px 26px;border-bottom:1px solid #eee;font-size:13px;vertical-align:top;color:#555"';
const tdR = 'style="padding:6px 10px;border-bottom:1px solid #eee;font-size:13px;text-align:right;white-space:nowrap;vertical-align:top"';
const klein = 'style="font-size:11px;color:#888"';
const rot = 'style="color:#b00020"';

const aufforderung = (z) => z.aufforderungErhalten
  ? esc(datum(z.ersteAufforderung)) + (z.anzahlAufforderungen > 1
    ? `<br><span ${klein}>${esc(z.anzahlAufforderungen)}×, zuletzt ${esc(datum(z.letzteAufforderung))}</span>` : '')
  : `<span ${rot}>keine</span>`;

const tage = (z) => !z.aufforderungErhalten ? ''
  : z.aufforderungAbAlterTage ? `<strong ${rot}>${esc(z.tageSeitAufforderung)}</strong>`
  : esc(z.tageSeitAufforderung);

const kunde = (z) => `${esc(z.kunde)}<br><span ${klein}>${esc(z.email)}</span>`;
const link = (z) => `<a href="${esc(z.adminUrl)}">${esc(z.orderName)}</a>`;

const offenZeilen = offen.map(z => `
  <tr>
    <td ${td}>${link(z)}</td>
    <td ${td}>${esc(datum(z.createdAt))}</td>
    <td ${td}>${kunde(z)}</td>
    <td ${tdR}>${esc(betrag(z.mehrbetrag, z.currency))}</td>
    <td ${tdR}><strong>${esc(betrag(z.offenerBetrag, z.currency))}</strong></td>
    <td ${td}>${esc(statusText(z.financialStatus))}</td>
    <td ${td}>${aufforderung(z)}</td>
    <td ${tdR}>${tage(z)}</td>
    <td ${td}>${z.grund ? `<span ${klein}>${esc(z.grund)}</span>` : ''}</td>
  </tr>`).join('');

const offenTabelle = offen.length ? `
<table cellspacing="0" cellpadding="0" style="border-collapse:collapse;width:100%;max-width:1200px">
  <tr>
    <th ${th}>Bestellung</th>
    <th ${th}>Bestellt am</th>
    <th ${th}>Kunde</th>
    <th ${thR}>Mehrbetrag</th>
    <th ${thR}>Offen</th>
    <th ${th}>Zahlstatus</th>
    <th ${th}>Aufgefordert am</th>
    <th ${thR}>Tage</th>
    <th ${th}>Hinweis</th>
  </tr>
  ${offenZeilen}
</table>` : '<p style="font-size:13px">Kein offener Mehrbetrag.</p>';

const ausgeglichenZeilen = ausgeglichen.slice(0, MAX_AUSGEGLICHEN).map(z => `
  <tr>
    <td ${td}>${link(z)}</td>
    <td ${td}>${esc(datum(z.createdAt))}</td>
    <td ${td}>${kunde(z)}</td>
    <td ${tdR}>${esc(betrag(z.mehrbetrag, z.currency))}</td>
    <td ${td}>${aufforderung(z)}</td>
  </tr>`).join('');

const ausgeglichenBlock = ausgeglichen.length ? `
<h3 style="font-size:14px;margin:28px 0 6px">Ausgeglichen (${ausgeglichen.length})</h3>
<table cellspacing="0" cellpadding="0" style="border-collapse:collapse;width:100%;max-width:900px">
  <tr>
    <th ${th}>Bestellung</th>
    <th ${th}>Bestellt am</th>
    <th ${th}>Kunde</th>
    <th ${thR}>Mehrbetrag</th>
    <th ${th}>Aufgefordert am</th>
  </tr>
  ${ausgeglichenZeilen}
</table>
${ausgeglichen.length > MAX_AUSGEGLICHEN
    ? `<p style="font-size:12px;color:#666">… und ${ausgeglichen.length - MAX_AUSGEGLICHEN} weitere (vollständig im n8n-Report)</p>` : ''}` : '';

const sonstigeBlock = sonstige.length ? `
<h3 style="font-size:14px;margin:28px 0 4px">Partially paid ohne Mehrbetrag aus Bearbeitung (${sonstige.length})</h3>
<p style="font-size:12px;color:#666;margin:0 0 6px">Zur Kontrolle: teilweise bezahlt, aber nicht durch eine Bearbeitung teurer geworden.</p>
<ul style="font-size:13px;margin:0;padding-left:18px">
  ${sonstige.slice(0, MAX_KONTROLLE).map(z => `<li>${link(z)}
    · ${esc(datum(z.createdAt))} · offen ${esc(betrag(z.offenerBetrag, z.currency))}
    · ${z.bearbeitet ? 'bearbeitet, Summe ' + esc(betrag(z.mehrbetrag, z.currency)) + ' zum Original' : 'nicht bearbeitet'}</li>`).join('')}
  ${sonstige.length > MAX_KONTROLLE ? `<li>… und ${sonstige.length - MAX_KONTROLLE} weitere (vollständig im n8n-Report)</li>` : ''}
</ul>` : '';

const fehlerBlock = fehler.length ? `
<h3 style="font-size:14px;margin:28px 0 6px;color:#b00020">Nicht prüfbar (${fehler.length})</h3>
<ul style="font-size:13px;margin:0;padding-left:18px">
  ${fehler.map(f => `<li>${esc(f.orderName || f.orderId)}: ${esc(f.status)} – ${esc(f.grund)}</li>`).join('')}
</ul>` : '';

const warnung = zus.paginationVollstaendig === false ? `
<p style="font-size:13px;color:#b00020;margin:0 0 16px"><strong>UNVOLLSTÄNDIG:</strong>
  Config.maxSeiten erreicht, nicht alle Bestellungen des Zeitraums gelesen. Zahlen nicht belastbar.</p>` : '';

const zeitraumText = `${datum(zus.zeitraumVon)} bis ${zus.zeitraumBis === 'jetzt' ? 'heute' : datum(zus.zeitraumBis)}`;

const mailText = `
<div style="font-family:Arial,Helvetica,sans-serif;color:#222">
  <h2 style="font-size:18px;margin:0 0 4px">Shopify – Mehrbeträge nach Bestellbearbeitung</h2>
  <p style="font-size:13px;color:#666;margin:0 0 16px">
    Bestellungen vom ${esc(zeitraumText)} &middot; ${esc(zus.bestellungenGeprueft)} geprüft,
    davon ${esc(zus.bestellungenBearbeitet)} bearbeitet
  </p>
  ${warnung}

  <table cellspacing="0" cellpadding="0" style="border-collapse:collapse;margin:0 0 20px">
    <tr><td ${td}><strong>Betroffen: nach Bearbeitung teurer als bestellt</strong></td><td ${tdR}><strong>${esc(zus.betroffen)}</strong></td><td ${tdR}><strong>${esc(summenText(zus.summeMehrbetrag))}</strong></td></tr>
    <tr><td ${td}>Zahlungsaufforderung erhalten</td><td ${tdR}>${esc(zus.zahlungsaufforderungErhalten)}</td><td ${tdR}></td></tr>
    <tr><td ${td}>ausgeglichen</td><td ${tdR}>${esc(zus.ausgeglichen)}</td><td ${tdR}>${esc(summenText(zus.summeAusgeglichen))}</td></tr>
    <tr><td ${tdE}>mit / ohne Zahlungsaufforderung</td><td ${tdR}>${esc(zus.ausgeglichenMitAufforderung)} / ${esc(zus.ausgeglichenOhneAufforderung)}</td><td ${tdR}></td></tr>
    <tr><td ${td}><strong>noch offen</strong></td><td ${tdR}><strong>${esc(zus.offen)}</strong></td><td ${tdR}><strong>${esc(summenText(zus.summeOffen))}</strong></td></tr>
    <tr><td ${tdE}>mit / ohne Zahlungsaufforderung</td><td ${tdR}>${esc(zus.offenMitAufforderung)} / ${esc(zus.offenOhneAufforderung)}</td><td ${tdR}></td></tr>
    <tr><td ${tdE}>Zahlungsaufforderung ${esc(zus.alterTage)}+ Tage alt</td><td ${tdR}>${esc(zus.offenAufforderungAbAlterTage)}</td><td ${tdR}></td></tr>
    <tr><td ${td}>Partially paid ohne Mehrbetrag aus Bearbeitung</td><td ${tdR}>${esc(zus.partiallyPaidOhneMehrbetrag)}</td><td ${tdR}></td></tr>
    <tr><td ${td}>betroffen, aber storniert (nicht gezählt)</td><td ${tdR}>${esc(zus.storniert)}</td><td ${tdR}></td></tr>
    <tr><td ${td}>nicht prüfbar</td><td ${tdR}>${esc(zus.fehler)}</td><td ${tdR}></td></tr>
  </table>

  <h3 style="font-size:14px;margin:0 0 6px">Noch offen (${offen.length})</h3>
  ${offenTabelle}
  ${ausgeglichenBlock}
  ${sonstigeBlock}
  ${fehlerBlock}

  <p style="font-size:12px;color:#888;margin-top:24px">
    Workflow-ID ${esc($workflow.id)}, Lauf ${esc(zus.lauf)}
  </p>
</div>`;

const titel = `Bücherbüchse | Mehrbeträge nach Bestellbearbeitung: ${zus.betroffen} betroffen, `
  + `${zus.zahlungsaufforderungErhalten} aufgefordert, ${zus.ausgeglichen} ausgeglichen, ${zus.offen} offen`
  + (Number(zus.offen) > 0 ? ` (${summenText(zus.summeOffen)})` : '');

return [{ json: { titel, mailText, anzahlOffen: offen.length } }];
